    solutions = []
    for n in range(7**m, 7**(m+1)):
        digits = []
        temp_n = n
        for _ in range(m+1):
            digits.append(temp_n % 7)
            temp_n //= 7

        sum_a = 0
        for i in range(m+1):
            a_i = 0
            current_digits = []
            for j in range(m, -1, -1):
                if j == i:
                    continue
                current_digits.append(digits[j])
            for d in current_digits:
                a_i = a_i * 7 + d
            sum_a += a_i

        if sum_a == n:
            count += 1
            solutions.append(n)
